      return Err(ParseNodeIdError::too_large(Self::MAX_SIZE, src.len()));
    }

    Ok(Self(src))
  }

  /// converts the `Id` into a `&str`.
  #[inline]
  pub const fn as_str(&self) -> &'a str {
    self.0
  }

  /// Returns a byte slice.
