    })
  }

  async fn resolve(&self, address: &Self::Address) -> Result<Self::ResolvedAddress, Self::Error> {
    let Some(port) = address.port() else {
      return Err(
        std::io::Error::new(std::io::ErrorKind::InvalidInput, "address missing port").into(),
